-- seed.sql — 한국고등학교 dataset for the in-browser SQL playground
-- Generated by scripts/gen-seed-sql.py from Pages/figures/data/*.csv
-- Idempotent: safely re-runnable.

PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;

DROP TABLE IF EXISTS teachers;
CREATE TABLE teachers (
    "교사번호" INTEGER PRIMARY KEY,
    "이름" TEXT,
    "부서" TEXT,
    "담당교과" TEXT,
    "입사일" TEXT
);

DROP TABLE IF EXISTS courses;
CREATE TABLE courses (
    "과목코드" TEXT PRIMARY KEY,
    "과목명" TEXT,
    "단위수" INTEGER
);

DROP TABLE IF EXISTS books;
CREATE TABLE books (
    "도서번호" INTEGER PRIMARY KEY,
    "제목" TEXT,
    "저자" TEXT,
    "출판사" TEXT,
    "ISBN" TEXT,
    "청구기호" TEXT
);

DROP TABLE IF EXISTS students;
CREATE TABLE students (
    "학번" INTEGER PRIMARY KEY,
    "이름" TEXT,
    "학년" INTEGER,
    "반" INTEGER,
    "번호" INTEGER,
    "성별" TEXT,
    "생년월일" TEXT,
    "입학일" TEXT,
    "보호자연락처" TEXT
);

DROP TABLE IF EXISTS classes;
CREATE TABLE classes (
    "학급번호" INTEGER PRIMARY KEY,
    "학년" INTEGER,
    "반" INTEGER,
    "담임교사번호" INTEGER,
    "교실" TEXT,
    FOREIGN KEY ("담임교사번호") REFERENCES teachers("교사번호")
);

DROP TABLE IF EXISTS clubs;
CREATE TABLE clubs (
    "동아리번호" INTEGER PRIMARY KEY,
    "이름" TEXT,
    "담당교사번호" INTEGER,
    "활동요일" TEXT,
    FOREIGN KEY ("담당교사번호") REFERENCES teachers("교사번호")
);

DROP TABLE IF EXISTS scores;
CREATE TABLE scores (
    "성적ID" INTEGER PRIMARY KEY,
    "학번" INTEGER,
    "과목코드" TEXT,
    "학기" TEXT,
    "점수" INTEGER,
    FOREIGN KEY ("학번") REFERENCES students("학번"),
    FOREIGN KEY ("과목코드") REFERENCES courses("과목코드")
);

DROP TABLE IF EXISTS book_loans;
CREATE TABLE book_loans (
    "대출ID" INTEGER PRIMARY KEY,
    "학번" INTEGER,
    "도서번호" INTEGER,
    "대출일" TEXT,
    "반납예정일" TEXT,
    "반납일" TEXT,
    FOREIGN KEY ("학번") REFERENCES students("학번"),
    FOREIGN KEY ("도서번호") REFERENCES books("도서번호")
);

DROP TABLE IF EXISTS club_members;
CREATE TABLE club_members (
    "동아리번호" INTEGER,
    "학번" INTEGER,
    "가입일" TEXT,
    "직책" TEXT,
    PRIMARY KEY ("동아리번호", "학번"),
    FOREIGN KEY ("동아리번호") REFERENCES clubs("동아리번호"),
    FOREIGN KEY ("학번") REFERENCES students("학번")
);

-- ── Lesson 11-12 lab: pre-built denormalized example ──
DROP TABLE IF EXISTS 통합성적표_원본;
CREATE TABLE 통합성적표_원본 AS
  SELECT s.학번, s.이름 AS 학생이름, s.학년, s.반, s.생년월일,
         t.이름 AS 담임이름, t.부서 AS 담임부서, t.담당교과 AS 담임담당교과,
         co.과목명, co.단위수, sc.학기, sc.점수
  FROM students s
  JOIN classes c     ON c.학년 = s.학년 AND c.반 = s.반
  JOIN teachers t    ON t.교사번호 = c.담임교사번호
  JOIN scores sc     ON sc.학번 = s.학번
  JOIN courses co    ON co.과목코드 = sc.과목코드
  ORDER BY s.학번, sc.학기, co.과목코드;
-- NOTE: 같은 담임/학급 정보가 여러 행에 반복됨. 1NF→2NF→3NF 분해
--       대상으로 사용. (정규화 결과는 위쪽의 정상 테이블들과 같다.)
COMMIT;
PRAGMA foreign_keys = ON;
-- 9 tables, 5797 rows total + 1 denormalized teaching table (통합성적표_원본)
